cat > proxy.ts <<'EOF'
import { NextResponse, type NextRequest } from "next/server";
import { listBookSlugs } from "@/lib/book-files";

/**
 * Answers unknown book slugs with the 404 page. Rewriting to a path that
 * matches no route makes Next.js render `app/not-found.tsx` with a 404 status.
 */
export async function proxy(request: NextRequest) {
  const encoded = request.nextUrl.pathname.slice("/books/".length);
  let slug: string;
  try {
    slug = decodeURIComponent(encoded);
  } catch {
    slug = "";
  }

  const slugs = await listBookSlugs();
  if (slugs.includes(slug)) return NextResponse.next();

  return NextResponse.rewrite(new URL("/_unknown-book", request.url));
}

export const config = {
  matcher: "/books/:slug",
};
EOF
